// ProviderVersionSelected satisfies the [providers.InstallerHook] interface.
// When a provider version is selected, this method performs policy evaluation for the provider,
// and aborts the installation if the policy evaluation fails.
func (p *providerPolicyHook) ProviderVersionSelected(ctx context.Context, provider addrs.Provider, version string) error {
	// If the client is nil, then policy evaluation is disabled, so we can skip.
	if p.client == nil {
		return nil
	}
	log.Println("[DEBUG] init: evaluating policy for provider", provider.String(), version)
	result := p.client.EvaluateProvider(ctx, policy.EvaluationRequest[*proto.PolicyEvaluateProviderRequest_ProviderMetadata]{
		Target: provider.Type,

		// Configuration attributes may not be available during init, so we will send an unknown
		// dynamic value to the policy client.
		Attrs: policy.PolicyValue{Raw: cty.DynamicVal},
		Meta: &proto.PolicyEvaluateProviderRequest_ProviderMetadata{
			Name:      provider.Type,
			Namespace: provider.Namespace,
			Source:    provider.String(),
			Version:   version,
		},
	})
	// We use the root module as the module for provider configs since the version resolution
	// is ambiguous, and we do not know which module the provider config belongs to.
	addr := addrs.AbsProviderConfig{Provider: provider, Module: addrs.RootModule}
	providerConfig := p.rootModule.ProviderConfigs[provider.Type]

	p.policyResults.AddProvider(addr, result, providerConfig)
	log.Println("[DEBUG] init: policy result for provider", provider.String(), version, "overall", result.Overall)
	if result.Overall != policy.AllowResult {
		return fmt.Errorf("Provider download blocked due to policy violations. Please review other diagnostics for details.")
	}

	return nil
}

	// The expected values to be sent for policy evaluation.
	expectedApply := map[string]cty.Value{
		"test": cty.ObjectVal(map[string]cty.Value{
			"value": cty.StringVal("foo"),
		}),
		"test_resource": cty.ObjectVal(map[string]cty.Value{
			"value":           cty.NullVal(cty.String),
			"sensitive_value": cty.StringVal("foo"),
		}),
		"test_instance": cty.ObjectVal(map[string]cty.Value{
			"value":           cty.StringVal("parent"), // was unknown in the plan
			"sensitive_value": cty.NullVal(cty.String),
		}),
	}
	actualApply := make(map[string]cty.Value)

	applyPolicyClient.EvaluateFn = func(ctx context.Context, req policy.EvaluationRequest[*proto.PolicyEvaluateResourceRequest_ResourceMetadata]) policy.EvaluationResponse {
		var actual cty.Value
		attrs := req.Attrs
		target := req.Target
		if !attrs.Raw.IsNull() {
			mp := attrs.Raw.AsValueMap()
			actual = cty.ObjectVal(map[string]cty.Value{
				"value":           mp["value"],
				"sensitive_value": mp["sensitive_value"],
			})
		}
		actualApply[target] = actual

		if actual.Type().HasAttribute("sensitive_value") {
			if !actual.GetAttr("sensitive_value").IsNull() && len(attrs.RedactedPaths) == 0 {
				t.Errorf("Expected redacted paths for sensitive attributes to be included in the request")
			}

			for _, path := range attrs.RedactedPaths {
				if !path.Equals(cty.Path{cty.GetAttrStep{Name: "sensitive_value"}}) {
					t.Errorf("Unexpected redacted path: %s", path)
				}
			}
		}

		// this return does not actually do anything
		return policy.EvaluationResponse{Overall: policy.AllowResult}
	}

	applyPolicyClient.EvaluateProviderFn = func(ctx context.Context, req policy.EvaluationRequest[*proto.PolicyEvaluateProviderRequest_ProviderMetadata]) policy.EvaluationResponse {
		var actual cty.Value
		attrs := req.Attrs
		target := req.Target
		if !attrs.Raw.IsNull() {
			mp := attrs.Raw.AsValueMap()
			actual = cty.ObjectVal(map[string]cty.Value{
				"value": mp["value"],
			})
		}
		actualApply[target] = actual

		if actual.Type().HasAttribute("value") {
			if !actual.GetAttr("value").IsNull() && len(attrs.RedactedPaths) == 0 {
				t.Errorf("Expected redacted paths for sensitive attributes to be included in the request")
			}

			for _, path := range attrs.RedactedPaths {
				if !path.Equals(cty.GetAttrPath("value")) {
					t.Errorf("Unexpected redacted path: %s", path)
				}
			}
		}

		return policy.EvaluationResponse{Overall: policy.AllowResult}
	}

	t.Cleanup(func() {
		if diff := cmp.Diff(actualApply, expectedApply, cmp.Comparer(cty.Value.RawEquals)); diff != "" {
			t.Errorf("Unexpected diff (-got +want):\n%s", diff)
		}
	})

	_, diags = ctx.Apply(plan, mod, &ApplyOpts{
		PolicyClient: applyPolicyClient,
	})
	tfdiags.AssertNoDiagnostics(t, diags)

}

